341: /**
342:  * Base worker class. Handles the async work. Derived classes can override the
343:  * following virtual methods (listed in the order in which they're called):
344:  *
345:  * - DoExecute (abstract, worker pool thread): main work
346:  * - HandleOKCallback (main thread): call JS callback on success
347:  * - HandleErrorCallback (main thread): call JS callback on error
348:  * - DoFinally (main thread): do cleanup regardless of success
349:  */
350: struct BaseWorker {
351:   // Note: storing env is discouraged as we'd end up using it in unsafe places.
352:   BaseWorker (napi_env env,
353:               Database* database,
354:               napi_value callback,
355:               const char* resourceName)
356:     : database_(database), errMsg_(NULL) {
357:     NAPI_STATUS_THROWS_VOID(napi_create_reference(env, callback, 1, &callbackRef_));
358:     napi_value asyncResourceName;
359:     NAPI_STATUS_THROWS_VOID(napi_create_string_utf8(env, resourceName,
360:                                                NAPI_AUTO_LENGTH,
361:                                                &asyncResourceName));
362:     NAPI_STATUS_THROWS_VOID(napi_create_async_work(env, callback,
363:                                               asyncResourceName,
364:                                               BaseWorker::Execute,
365:                                               BaseWorker::Complete,
366:                                               this, &asyncWork_));
367:   }
368: 
369:   virtual ~BaseWorker () {
370:     delete [] errMsg_;
371:   }
372: 
373:   static void Execute (napi_env env, void* data) {
374:     BaseWorker* self = (BaseWorker*)data;
375: 
376:     // Don't pass env to DoExecute() because use of Node-API
377:     // methods should generally be avoided in async work.
378:     self->DoExecute();
379:   }
380: 
381:   bool SetStatus (leveldb::Status status) {
382:     status_ = status;
383:     if (!status.ok()) {
384:       SetErrorMessage(status.ToString().c_str());
385:       return false;
386:     }
387:     return true;
388:   }
389: 
390:   void SetErrorMessage(const char *msg) {
391:     delete [] errMsg_;
392:     size_t size = strlen(msg) + 1;
393:     errMsg_ = new char[size];
394:     memcpy(errMsg_, msg, size);
395:   }
396: 
397:   virtual void DoExecute () = 0;
398: 
399:   static void Complete (napi_env env, napi_status status, void* data) {
400:     BaseWorker* self = (BaseWorker*)data;
401: 
402:     self->DoComplete(env);
403:     self->DoFinally(env);
404:   }
405: 
406:   void DoComplete (napi_env env) {
407:     napi_value callback;
408:     napi_get_reference_value(env, callbackRef_, &callback);
409: 
410:     if (status_.ok()) {
411:       HandleOKCallback(env, callback);
412:     } else {
413:       HandleErrorCallback(env, callback);
414:     }
415:   }
416: 
417:   virtual void HandleOKCallback (napi_env env, napi_value callback) {
418:     napi_value argv;
419:     napi_get_null(env, &argv);
420:     CallFunction(env, callback, 1, &argv);
421:   }
422: 
423:   virtual void HandleErrorCallback (napi_env env, napi_value callback) {
424:     napi_value argv = CreateError(env, errMsg_);
425:     CallFunction(env, callback, 1, &argv);
426:   }
427: 
428:   virtual void DoFinally (napi_env env) {
429:     napi_delete_reference(env, callbackRef_);
430:     napi_delete_async_work(env, asyncWork_);
431: 
432:     delete this;
433:   }
434: 
435:   void Queue (napi_env env) {
436:     napi_queue_async_work(env, asyncWork_);
437:   }
438: 
439:   Database* database_;
440: 
441: private:
442:   napi_ref callbackRef_;
443:   napi_async_work asyncWork_;
444:   leveldb::Status status_;
445:   char *errMsg_;
446: };
