448: /**
449:  * Owns the LevelDB storage, cache, filter policy and iterators.
450:  */
451: struct Database {
452:   Database ()
453:     : db_(NULL),
454:       blockCache_(NULL),
455:       filterPolicy_(leveldb::NewBloomFilterPolicy(10)),
456:       currentIteratorId_(0),
457:       pendingCloseWorker_(NULL),
458:       ref_(NULL),
459:       priorityWork_(0) {}
460: 
461:   ~Database () {
462:     if (db_ != NULL) {
463:       delete db_;
464:       db_ = NULL;
465:     }
466:   }
467: 
468:   leveldb::Status Open (const leveldb::Options& options,
469:                         const char* location) {
470:     return leveldb::DB::Open(options, location, &db_);
471:   }
472: 
473:   void CloseDatabase () {
474:     delete db_;
475:     db_ = NULL;
476:     if (blockCache_) {
477:       delete blockCache_;
478:       blockCache_ = NULL;
479:     }
480:   }
481: 
482:   leveldb::Status Put (const leveldb::WriteOptions& options,
483:                        leveldb::Slice key,
484:                        leveldb::Slice value) {
485:     return db_->Put(options, key, value);
486:   }
487: 
488:   leveldb::Status Get (const leveldb::ReadOptions& options,
489:                        leveldb::Slice key,
490:                        std::string& value) {
491:     return db_->Get(options, key, &value);
492:   }
493: 
494:   leveldb::Status Del (const leveldb::WriteOptions& options,
495:                        leveldb::Slice key) {
496:     return db_->Delete(options, key);
497:   }
498: 
499:   leveldb::Status WriteBatch (const leveldb::WriteOptions& options,
500:                               leveldb::WriteBatch* batch) {
501:     return db_->Write(options, batch);
502:   }
503: 
504:   uint64_t ApproximateSize (const leveldb::Range* range) {
505:     uint64_t size = 0;
506:     db_->GetApproximateSizes(range, 1, &size);
507:     return size;
508:   }
509: 
510:   void CompactRange (const leveldb::Slice* start,
511:                      const leveldb::Slice* end) {
512:     db_->CompactRange(start, end);
513:   }
514: 
515:   void GetProperty (const leveldb::Slice& property, std::string* value) {
516:     db_->GetProperty(property, value);
517:   }
518: 
519:   const leveldb::Snapshot* NewSnapshot () {
520:     return db_->GetSnapshot();
521:   }
522: 
523:   leveldb::Iterator* NewIterator (leveldb::ReadOptions* options) {
524:     return db_->NewIterator(*options);
525:   }
526: 
527:   void ReleaseSnapshot (const leveldb::Snapshot* snapshot) {
528:     return db_->ReleaseSnapshot(snapshot);
529:   }
530: 
531:   void AttachIterator (napi_env env, uint32_t id, Iterator* iterator) {
532:     iterators_[id] = iterator;
533:     IncrementPriorityWork(env);
534:   }
535: 
536:   void DetachIterator (napi_env env, uint32_t id) {
537:     iterators_.erase(id);
538:     DecrementPriorityWork(env);
539:   }
540: 
541:   void IncrementPriorityWork (napi_env env) {
542:     napi_reference_ref(env, ref_, &priorityWork_);
543:   }
544: 
545:   void DecrementPriorityWork (napi_env env) {
546:     napi_reference_unref(env, ref_, &priorityWork_);
547: 
548:     if (priorityWork_ == 0 && pendingCloseWorker_ != NULL) {
549:       pendingCloseWorker_->Queue(env);
550:       pendingCloseWorker_ = NULL;
551:     }
552:   }
553: 
554:   bool HasPriorityWork () const {
555:     return priorityWork_ > 0;
556:   }
557: 
558:   leveldb::DB* db_;
559:   leveldb::Cache* blockCache_;
560:   const leveldb::FilterPolicy* filterPolicy_;
561:   uint32_t currentIteratorId_;
562:   BaseWorker *pendingCloseWorker_;
563:   std::map< uint32_t, Iterator * > iterators_;
564:   napi_ref ref_;
565: 
566: private:
567:   uint32_t priorityWork_;
568: };
