587: /**
588:  * Owns a leveldb iterator.
589:  */
590: struct BaseIterator {
591:   BaseIterator(Database* database,
592:                const bool reverse,
593:                std::string* lt,
594:                std::string* lte,
595:                std::string* gt,
596:                std::string* gte,
597:                const int limit,
598:                const bool fillCache)
599:     : database_(database),
600:       hasEnded_(false),
601:       didSeek_(false),
602:       reverse_(reverse),
603:       lt_(lt),
604:       lte_(lte),
605:       gt_(gt),
606:       gte_(gte),
607:       limit_(limit),
608:       count_(0) {
609:     options_ = new leveldb::ReadOptions();
610:     options_->fill_cache = fillCache;
611:     options_->snapshot = database->NewSnapshot();
612:     dbIterator_ = database_->NewIterator(options_);
613:   }
614: 
615:   virtual ~BaseIterator () {
616:     assert(hasEnded_);
617: 
618:     if (lt_ != NULL) delete lt_;
619:     if (gt_ != NULL) delete gt_;
620:     if (lte_ != NULL) delete lte_;
621:     if (gte_ != NULL) delete gte_;
622: 
623:     delete options_;
624:   }
625: 
626:   bool DidSeek () const {
627:     return didSeek_;
628:   }
629: 
630:   /**
631:    * Seek to the first relevant key based on range options.
632:    */
633:   void SeekToRange () {
634:     didSeek_ = true;
635: 
636:     if (!reverse_ && gte_ != NULL) {
637:       dbIterator_->Seek(*gte_);
638:     } else if (!reverse_ && gt_ != NULL) {
639:       dbIterator_->Seek(*gt_);
640: 
641:       if (dbIterator_->Valid() && dbIterator_->key().compare(*gt_) == 0) {
642:         dbIterator_->Next();
643:       }
644:     } else if (reverse_ && lte_ != NULL) {
645:       dbIterator_->Seek(*lte_);
646: 
647:       if (!dbIterator_->Valid()) {
648:         dbIterator_->SeekToLast();
649:       } else if (dbIterator_->key().compare(*lte_) > 0) {
650:         dbIterator_->Prev();
651:       }
652:     } else if (reverse_ && lt_ != NULL) {
653:       dbIterator_->Seek(*lt_);
654: 
655:       if (!dbIterator_->Valid()) {
656:         dbIterator_->SeekToLast();
657:       } else if (dbIterator_->key().compare(*lt_) >= 0) {
658:         dbIterator_->Prev();
659:       }
660:     } else if (reverse_) {
661:       dbIterator_->SeekToLast();
662:     } else {
663:       dbIterator_->SeekToFirst();
664:     }
665:   }
666: 
667:   /**
668:    * Seek manually (during iteration).
669:    */
670:   void Seek (leveldb::Slice& target) {
671:     didSeek_ = true;
672: 
673:     if (OutOfRange(target)) {
674:       return SeekToEnd();
675:     }
676: 
677:     dbIterator_->Seek(target);
678: 
679:     if (dbIterator_->Valid()) {
680:       int cmp = dbIterator_->key().compare(target);
681:       if (reverse_ ? cmp > 0 : cmp < 0) {
682:         Next();
683:       }
684:     } else {
685:       SeekToFirst();
686:       if (dbIterator_->Valid()) {
687:         int cmp = dbIterator_->key().compare(target);
688:         if (reverse_ ? cmp > 0 : cmp < 0) {
689:           SeekToEnd();
690:         }
691:       }
692:     }
693:   }
694: 
695:   void End () {
696:     if (!hasEnded_) {
697:       hasEnded_ = true;
698:       delete dbIterator_;
699:       dbIterator_ = NULL;
700:       database_->ReleaseSnapshot(options_->snapshot);
701:     }
702:   }
703: 
704:   bool Valid () const {
705:     return dbIterator_->Valid() && !OutOfRange(dbIterator_->key());
706:   }
707: 
708:   bool Increment () {
709:     return limit_ < 0 || ++count_ <= limit_;
710:   }
711: 
712:   void Next () {
713:     if (reverse_) dbIterator_->Prev();
714:     else dbIterator_->Next();
715:   }
716: 
717:   void SeekToFirst () {
718:     if (reverse_) dbIterator_->SeekToLast();
719:     else dbIterator_->SeekToFirst();
720:   }
721: 
722:   void SeekToLast () {
723:     if (reverse_) dbIterator_->SeekToFirst();
724:     else dbIterator_->SeekToLast();
725:   }
726: 
727:   void SeekToEnd () {
728:     SeekToLast();
729:     Next();
730:   }
731: 
732:   leveldb::Slice CurrentKey () const {
733:     return dbIterator_->key();
734:   }
735: 
736:   leveldb::Slice CurrentValue () const {
737:     return dbIterator_->value();
738:   }
739: 
740:   leveldb::Status Status () const {
741:     return dbIterator_->status();
742:   }
743: 
744:   bool OutOfRange (const leveldb::Slice& target) const {
745:     // TODO: benchmark to see if this is worth it
746:     // if (upperBoundOnly && !reverse_) {
747:     //   return ((lt_  != NULL && target.compare(*lt_) >= 0) ||
748:     //           (lte_ != NULL && target.compare(*lte_) > 0));
749:     // }
750: 
751:     return ((lt_  != NULL && target.compare(*lt_) >= 0) ||
752:             (lte_ != NULL && target.compare(*lte_) > 0) ||
753:             (gt_  != NULL && target.compare(*gt_) <= 0) ||
754:             (gte_ != NULL && target.compare(*gte_) < 0));
755:   }
756: 
757:   Database* database_;
758:   bool hasEnded_;
759: 
760: private:
761:   leveldb::Iterator* dbIterator_;
762:   bool didSeek_;
763:   const bool reverse_;
764:   std::string* lt_;
765:   std::string* lte_;
766:   std::string* gt_;
767:   std::string* gte_;
768:   const int limit_;
769:   int count_;
770:   leveldb::ReadOptions* options_;
771: };
