773: /**
774:  * Extends BaseIterator for reading it from JS land.
775:  */
776: struct Iterator final : public BaseIterator {
777:   Iterator (Database* database,
778:             const uint32_t id,
779:             const bool reverse,
780:             const bool keys,
781:             const bool values,
782:             const int limit,
783:             std::string* lt,
784:             std::string* lte,
785:             std::string* gt,
786:             std::string* gte,
787:             const bool fillCache,
788:             const bool keyAsBuffer,
789:             const bool valueAsBuffer,
790:             const uint32_t highWaterMark)
791:     : BaseIterator(database, reverse, lt, lte, gt, gte, limit, fillCache),
792:       id_(id),
793:       keys_(keys),
794:       values_(values),
795:       keyAsBuffer_(keyAsBuffer),
796:       valueAsBuffer_(valueAsBuffer),
797:       highWaterMark_(highWaterMark),
798:       landed_(false),
799:       nexting_(false),
800:       isEnding_(false),
801:       endWorker_(NULL),
802:       ref_(NULL) {
803:   }
804: 
805:   ~Iterator () {}
806: 
807:   void Attach (napi_env env, napi_value context) {
808:     napi_create_reference(env, context, 1, &ref_);
809:     database_->AttachIterator(env, id_, this);
810:   }
811: 
812:   void Detach (napi_env env) {
813:     database_->DetachIterator(env, id_);
814:     if (ref_ != NULL) napi_delete_reference(env, ref_);
815:   }
816: 
817:   bool ReadMany (uint32_t size) {
818:     cache_.clear();
819:     size_t bytesRead = 0;
820: 
821:     while (true) {
822:       if (landed_) Next();
823:       if (!Valid() || !Increment()) break;
824: 
825:       if (keys_) {
826:         leveldb::Slice slice = CurrentKey();
827:         cache_.emplace_back(slice.data(), slice.size());
828:         bytesRead += slice.size();
829:       } else {
830:         cache_.emplace_back("");
831:       }
832: 
833:       if (values_) {
834:         leveldb::Slice slice = CurrentValue();
835:         cache_.emplace_back(slice.data(), slice.size());
836:         bytesRead += slice.size();
837:       } else {
838:         cache_.emplace_back("");
839:       }
840: 
841:       if (!landed_) {
842:         landed_ = true;
843:         return true;
844:       }
845: 
846:       if (bytesRead > highWaterMark_ || cache_.size() >= size * 2) {
847:         return true;
848:       }
849:     }
850: 
851:     return false;
852:   }
853: 
854:   const uint32_t id_;
855:   const bool keys_;
856:   const bool values_;
857:   const bool keyAsBuffer_;
858:   const bool valueAsBuffer_;
859:   const uint32_t highWaterMark_;
860:   bool landed_;
861:   bool nexting_;
862:   bool isEnding_;
863:   BaseWorker* endWorker_;
864:   std::vector<std::string> cache_;
865: 
866: private:
867:   napi_ref ref_;
868: };
