870: /**
871:  * Hook for when the environment exits. This hook will be called after
872:  * already-scheduled napi_async_work items have finished, which gives us
873:  * the guarantee that no db operations will be in-flight at this time.
874:  */
875: static void env_cleanup_hook (void* arg) {
876:   Database* database = (Database*)arg;
877: 
878:   // Do everything that db_close() does but synchronously. We're expecting that GC
879:   // did not (yet) collect the database because that would be a user mistake (not
880:   // closing their db) made during the lifetime of the environment. That's different
881:   // from an environment being torn down (like the main process or a worker thread)
882:   // where it's our responsibility to clean up. Note also, the following code must
883:   // be a safe noop if called before db_open() or after db_close().
884:   if (database && database->db_ != NULL) {
885:     std::map<uint32_t, Iterator*> iterators = database->iterators_;
886:     std::map<uint32_t, Iterator*>::iterator it;
887: 
888:     // TODO: does not do `napi_delete_reference(env, iterator->ref_)`. Problem?
889:     for (it = iterators.begin(); it != iterators.end(); ++it) {
890:       it->second->End();
891:     }
892: 
893:     // Having ended the iterators (and released snapshots) we can safely close.
894:     database->CloseDatabase();
895:   }
896: }
897: 
898: /**
899:  * Runs when a Database is garbage collected.
900:  */
901: static void FinalizeDatabase (napi_env env, void* data, void* hint) {
902:   if (data) {
903:     Database* database = (Database*)data;
904:     napi_remove_env_cleanup_hook(env, env_cleanup_hook, database);
905:     if (database->ref_ != NULL) napi_delete_reference(env, database->ref_);
906:     delete database;
907:   }
908: }
