910: /**
911:  * Returns a context object for a database.
912:  */
913: NAPI_METHOD(db_init) {
914:   Database* database = new Database();
915:   napi_add_env_cleanup_hook(env, env_cleanup_hook, database);
916: 
917:   napi_value result;
918:   NAPI_STATUS_THROWS(napi_create_external(env, database,
919:                                           FinalizeDatabase,
920:                                           NULL, &result));
921: 
922:   // Reference counter to prevent GC of database while priority workers are active
923:   NAPI_STATUS_THROWS(napi_create_reference(env, result, 0, &database->ref_));
924: 
925:   return result;
926: }
