971: /**
972:  * Open a database.
973:  */
974: NAPI_METHOD(db_open) {
975:   NAPI_ARGV(4);
976:   NAPI_DB_CONTEXT();
977:   NAPI_ARGV_UTF8_NEW(location, 1);
978: 
979:   napi_value options = argv[2];
980:   const bool createIfMissing = BooleanProperty(env, options, "createIfMissing", true);
981:   const bool errorIfExists = BooleanProperty(env, options, "errorIfExists", false);
982:   const bool compression = BooleanProperty(env, options, "compression", true);
983: 
984:   const uint32_t cacheSize = Uint32Property(env, options, "cacheSize", 8 << 20);
985:   const uint32_t writeBufferSize = Uint32Property(env, options , "writeBufferSize" , 4 << 20);
986:   const uint32_t blockSize = Uint32Property(env, options, "blockSize", 4096);
987:   const uint32_t maxOpenFiles = Uint32Property(env, options, "maxOpenFiles", 1000);
988:   const uint32_t blockRestartInterval = Uint32Property(env, options,
989:                                                  "blockRestartInterval", 16);
990:   const uint32_t maxFileSize = Uint32Property(env, options, "maxFileSize", 2 << 20);
991: 
992:   database->blockCache_ = leveldb::NewLRUCache(cacheSize);
993: 
994:   napi_value callback = argv[3];
995:   OpenWorker* worker = new OpenWorker(env, database, callback, location,
996:                                       createIfMissing, errorIfExists,
