1161: /**
1162:  * Worker class for getting many values.
1163:  */
1164: struct GetManyWorker final : public PriorityWorker {
1165:   GetManyWorker (napi_env env,
1166:                  Database* database,
1167:                  const std::vector<std::string>* keys,
1168:                  napi_value callback,
1169:                  const bool valueAsBuffer,
1170:                  const bool fillCache)
1171:     : PriorityWorker(env, database, callback, "leveldown.get.many"),
1172:       keys_(keys), valueAsBuffer_(valueAsBuffer) {
1173:       options_.fill_cache = fillCache;
1174:       options_.snapshot = database->NewSnapshot();
1175:     }
1176: 
1177:   ~GetManyWorker() {
1178:     delete keys_;
1179:   }
1180: 
1181:   void DoExecute () override {
1182:     cache_.reserve(keys_->size());
1183: 
1184:     for (const std::string& key: *keys_) {
1185:       std::string* value = new std::string();
1186:       leveldb::Status status = database_->Get(options_, key, *value);
1187: 
1188:       if (status.ok()) {
1189:         cache_.push_back(value);
1190:       } else if (status.IsNotFound()) {
1191:         delete value;
1192:         cache_.push_back(NULL);
1193:       } else {
1194:         delete value;
1195:         for (const std::string* value: cache_) {
1196:           if (value != NULL) delete value;
1197:         }
1198:         SetStatus(status);
1199:         break;
1200:       }
1201:     }
1202: 
1203:     database_->ReleaseSnapshot(options_.snapshot);
1204:   }
1205: 
1206:   void HandleOKCallback (napi_env env, napi_value callback) override {
1207:     size_t size = cache_.size();
1208:     napi_value array;
1209:     napi_create_array_with_length(env, size, &array);
1210: 
1211:     for (size_t idx = 0; idx < size; idx++) {
1212:       std::string* value = cache_[idx];
1213:       napi_value element;
1214:       Entry::Convert(env, value, valueAsBuffer_, &element);
1215:       napi_set_element(env, array, static_cast<uint32_t>(idx), element);
1216:       if (value != NULL) delete value;
1217:     }
1218: 
1219:     napi_value argv[2];
1220:     napi_get_null(env, &argv[0]);
1221:     argv[1] = array;
1222:     CallFunction(env, callback, 2, argv);
1223:   }
1224: 
1225: private:
1226:   leveldb::ReadOptions options_;
1227:   const std::vector<std::string>* keys_;
1228:   const bool valueAsBuffer_;
1229:   std::vector<std::string*> cache_;
1230: };
