1296: /**
1297:  * Worker class for deleting a range from a database.
1298:  */
1299: struct ClearWorker final : public PriorityWorker {
1300:   ClearWorker (napi_env env,
1301:                Database* database,
1302:                napi_value callback,
1303:                const bool reverse,
1304:                const int limit,
1305:                std::string* lt,
1306:                std::string* lte,
1307:                std::string* gt,
1308:                std::string* gte)
1309:     : PriorityWorker(env, database, callback, "leveldown.db.clear") {
1310:     iterator_ = new BaseIterator(database, reverse, lt, lte, gt, gte, limit, false);
1311:     writeOptions_ = new leveldb::WriteOptions();
1312:     writeOptions_->sync = false;
1313:   }
1314: 
1315:   ~ClearWorker () {
1316:     delete iterator_;
1317:     delete writeOptions_;
1318:   }
1319: 
1320:   void DoExecute () override {
1321:     iterator_->SeekToRange();
1322: 
1323:     // TODO: add option
1324:     uint32_t hwm = 16 * 1024;
1325:     leveldb::WriteBatch batch;
1326: 
1327:     while (true) {
1328:       size_t bytesRead = 0;
1329: 
1330:       while (bytesRead <= hwm && iterator_->Valid() && iterator_->Increment()) {
1331:         leveldb::Slice key = iterator_->CurrentKey();
1332:         batch.Delete(key);
1333:         bytesRead += key.size();
1334:         iterator_->Next();
1335:       }
1336: 
1337:       if (!SetStatus(iterator_->Status()) || bytesRead == 0) {
1338:         break;
1339:       }
1340: 
1341:       if (!SetStatus(database_->WriteBatch(*writeOptions_, &batch))) {
1342:         break;
1343:       }
1344: 
1345:       batch.Clear();
1346:     }
1347: 
1348:     iterator_->End();
1349:   }
1350: 
1351: private:
1352:   BaseIterator* iterator_;
1353:   leveldb::WriteOptions* writeOptions_;
1354: };
