1578: /**
1579:  * Create an iterator.
1580:  */
1581: NAPI_METHOD(iterator_init) {
1582:   NAPI_ARGV(2);
1583:   NAPI_DB_CONTEXT();
1584: 
1585:   napi_value options = argv[1];
1586:   const bool reverse = BooleanProperty(env, options, "reverse", false);
1587:   const bool keys = BooleanProperty(env, options, "keys", true);
1588:   const bool values = BooleanProperty(env, options, "values", true);
1589:   const bool fillCache = BooleanProperty(env, options, "fillCache", false);
1590:   const bool keyAsBuffer = BooleanProperty(env, options, "keyAsBuffer", true);
1591:   const bool valueAsBuffer = BooleanProperty(env, options, "valueAsBuffer", true);
1592:   const int limit = Int32Property(env, options, "limit", -1);
1593:   const uint32_t highWaterMark = Uint32Property(env, options, "highWaterMark",
1594:                                           16 * 1024);
1595: 
1596:   std::string* lt = RangeOption(env, options, "lt");
1597:   std::string* lte = RangeOption(env, options, "lte");
1598:   std::string* gt = RangeOption(env, options, "gt");
1599:   std::string* gte = RangeOption(env, options, "gte");
1600: 
1601:   const uint32_t id = database->currentIteratorId_++;
1602:   Iterator* iterator = new Iterator(database, id, reverse, keys,
1603:                                     values, limit, lt, lte, gt, gte, fillCache,
1604:                                     keyAsBuffer, valueAsBuffer, highWaterMark);
1605:   napi_value result;
1606: 
1607:   NAPI_STATUS_THROWS(napi_create_external(env, iterator,
1608:                                           FinalizeIterator,
1609:                                           NULL, &result));
1610: 
1611:   // Prevent GC of JS object before the iterator is ended (explicitly or on
1612:   // db close) and keep track of non-ended iterators to end them on db close.
1613:   iterator->Attach(env, result);
1614: 
1615:   return result;
1616: }
