1626:     napi_throw_error(env, NULL, "iterator has ended");
1627:   }
1628: 
1629:   leveldb::Slice target = ToSlice(env, argv[1]);
1630:   iterator->landed_ = false;
1631:   iterator->Seek(target);
1632: 
1633:   DisposeSliceBuffer(target);
