1662: /**
1663:  * Called by NAPI_METHOD(iterator_end) and also when closing
1664:  * open iterators during NAPI_METHOD(db_close).
1665:  */
1666: static void iterator_end_do (napi_env env, Iterator* iterator, napi_value cb) {
1667:   if (!iterator->isEnding_ && !iterator->hasEnded_) {
1668:     EndWorker* worker = new EndWorker(env, iterator, cb);
1669:     iterator->isEnding_ = true;
1670: 
1671:     if (iterator->nexting_) {
1672:       iterator->endWorker_ = worker;
1673:     } else {
1674:       worker->Queue(env);
