45: class Limiter {
46:  public:
47:   // Limit maximum number of resources to |n|.
48:   Limiter(intptr_t n) {
49:     SetAllowed(n);
50:   }
51: 
52:   // If another resource is available, acquire it and return true.
53:   // Else return false.
54:   bool Acquire() {
55:     if (GetAllowed() <= 0) {
56:       return false;
57:     }
58:     MutexLock l(&mu_);
59:     intptr_t x = GetAllowed();
60:     if (x <= 0) {
